                    cycle_len = visited_order[node] - visited_order[neighbor] + 1
                    if cycle_len >= 3 and cycle_len % 3 != 0:
                        return path[visited_order[neighbor]:visited_order[node] + 1]
                if neighbor not in visited_order:
                    visited_order[neighbor] = len(path)
                    if dfs_find_cycle(start, visited_order, {**path_set, neighbor}, path + [neighbor]):
                        return []
        return None

    # BFS/DFS approach to find cycles
    reachable = []

