            'idx': i + 1
        })

    def build_adj(removed_edge_indices):
        adj = [[] for _ in range(n + 1)]
        for i, edge in enumerate(edges):
            if edge['idx'] not in removed_edge_indices:
                adj[edge['u']].append((edge['v'], edge['idx']))
                adj[edge['v']].append((edge['u'], edge['idx']))
        return adj

    def bfs(start, end, adj):
        if start == end:
            return [0]
        visited = [False] * (n + 1)
        queue = deque([start])
        visited[start] = True
        while queue:
            u = queue.popleft()
            for v, _ in adj[u]:
                if not visited[v]:
                    visited[v] = True
                    queue.append(v)
                    if v == end:
                        return [0]
        return []

    def is_connected(start, end, adj):
        visited = [False] * (n + 1)
        queue = deque([start])
        visited[start] = True
        while queue:
            u = queue.popleft()
            for v, _ in adj[u]:
                if not visited[v]:
                    visited[v] = True
                    queue.append(v)
        return visited[end]

    # Check if already disconnected
    if not is_connected(s, t, build_adj(set())):
        return "0\n0\n"

    # Try removing 1 edge
