# Solution for the flow edge direction problem

def solution(input_str):
    lines = input_str.strip().split('\n')
    n, m = map(int, lines[0].split())

    # Parse edges
    edges = []
    for i in range(m):
        parts = list(map(int, lines[1 + i].split()))
        edges.append((parts[0], parts[1], parts[2], i))  # Store original index

    # Build adjacency list for BFS from source (node 1)
    adj = [[] for _ in range(n + 1)]
    for u, v, w, idx in edges:
        adj[u].append((v, w, idx))
        adj[v].append((u, w, idx))

    # BFS to compute levels (distances from source)
    level = [-1] * (n + 1)
    level[1] = 0
    queue = [1]
    visited = [False] * (n + 1)
    visited[1] = True

    while queue:
        u = queue.pop(0)
        for v, w, idx in adj[u]:
            if not visited[v]:
                visited[v] = True
                level[v] = level[u] + 1
                queue.append(v)

    # Output direction for each edge
    # 0 means u -> v, 1 means v -> u
    result = []
    for u, v, w, idx in edges:
        if level[u] < level[v]:
            result.append(0)  # u -> v
        elif level[v] < level[u]:
            result.append(1)  # v -> u
        else:
            # Same level - use node index as tiebreaker to avoid cycles
            if u < v:
                result.append(0)  # u -> v
            else:
                result.append(1)  # v -> u

    return '\n'.join(map(str, result))


