import heapq

def solution(input_str):
    lines = input_str.strip().split('\n')
    n, m = map(int, lines[0].split())

    adj = [[] for _ in range(n + 1)]
    for i in range(m):
        u, v, w = map(int, lines[i + 1].split())
        adj[u].append((v, w, i + 1))
        adj[v].append((u, w, i + 1))

    start = int(lines[m + 1])

    dist = [float('inf')] * (n + 1)
    dist[start] = 0
    pq = [(0, start)]

    while pq:
        d, u = heapq.heappop(pq)

        if d > dist[u]:
            continue

        for v, w, idx in adj[u]:
            if dist[u] + w < dist[v]:
                dist[v] = dist[u] + w
                heapq.heappush(pq, (dist[v], v))

    edge_weights = 0
    selected_edges = []

    for i in range(1, n + 1):
        if i == start:
            continue

        best_weight = float('inf')
        best_edge_idx = -1

        for parent, w, idx in adj[i]:
            if dist[parent] + w == dist[i]:
                if w < best_weight:
                    best_weight = w
                    best_edge_idx = idx

        if best_edge_idx != -1:
            edge_weights += best_weight
            selected_edges.append(best_edge_idx)

    result = f"{edge_weights}\n{' '.join(map(str, selected_edges))}"
    return result

