def compute_kmp_failure(pattern):
    m = len(pattern)
    failure = [0] * m
    j = 0
    for k in range(1, m):
        while j > 0 and pattern[k] != pattern[j]:
            j = failure[j-1]
        if pattern[k] == pattern[j]:
            j += 1
        failure[k] = j
    return failure

def compute_next_state(pat, prev, char):
    """Compute the new KMP match length after adding character."""
    n = len(pat)
    if n == 0:
        return 1
    k = prev
    while k > 0 and char != pat[k]:
        k = failure_state = [0] * n
        j = 0
        for idx in range(1, n):
            while j > 0 and pat[idx] != pat[j]:
                j = failure_state[j-1]
            if pat[idx] == pat[j]:
                j += 1
            failure_state[idx] = j

    k = prev
    while k > 0 and char != pat[k]:
        k = failure_state[k-1]
    if char == pat[k]:
        k += 1
    return k

def solution(input_str):
    parts = input_str.strip().split('\n')
    if len(parts) < 3:
        return '0'
    s1, s2, virus = parts[0], parts[1], parts[2]

    n, m, vlen = len(s1), len(s2), len(virus)
    if vlen == 0:
