    # If total sum is at most 1, no k > 1 divides it
    if total <= 1:
        return "-1"

    # With n=1, we can't move pieces between boxes
    if n == 1:
        return "-1"

    # Find all prime factors of total
    factors = set()
    d = 2
    temp = total
    while d * d <= temp:
        while temp % d == 0:
            factors.add(d)
            temp //= d
        d += 1
    if temp > 1:
        factors.add(temp)

    if not factors:
        return "-1"

    min_cost = float('inf')

    for k in factors:
        cost = 0
        prefix_sum = 0
        for x in a:
            prefix_sum = (prefix_sum + x) % k
            cost += min(prefix_sum, k - prefix_sum)

        if cost < min_cost:
            min_cost = cost

    return str(min_cost)

