            if ch == 'O':
                state_string += 'O'
                chocolates.add(c)
            else:
                state_string += '.'

    # Use memoization for game states
    memo = {}

    def can_win(state):
        """Check if current player can win from this state"""
        if state in memo:
            return memo[state]

        if not any(c == 'O' for c in state):
            return False

        # Try all valid moves (removing 1 or more consecutive chocolates in a row)
