    for line in lines[1:]:
        if line.strip():
            u, v = map(int, line.split())
            adj[u].append(v)
            adj[v].append(u)

    target = math.ceil(math.sqrt(n))

    # BFS from node 1 to build spanning tree and find depths
    visited = [False] * (n + 1)
    parent = [0] * (n + 1)
    depth = [-1] * (n + 1)

    queue = deque([1])
    visited[1] = True
    depth[1] = 0

    while queue:
        u = queue.popleft()
        for v in adj[u]:
            if not visited[v]:
                visited[v] = True
                parent[v] = u
                depth[v] = depth[u] + 1
                queue.append(v)
            elif v != parent[u]:
                # Found a back edge (cycle in graph)
                pass

    # Group nodes by their BFS depth (these form natural independent sets)
    layers = [[] for _ in range(n)]
    for i in range(1, n + 1):
        if depth[i] >= 0:
            layers[depth[i]].append(i)

    # Check if any layer has enough vertices for independent set
    for d in range(n):
        if len(layers[d]) >= target:
            result = sorted(layers[d])[:target]
            return f"1\n" + " ".join(map(str, result))

    # No sufficient layer, must find a cycle
    # Check all edges to find one that creates a >= target length cycle
    for u in range(1, n + 1):
        for v in adj[u]:
            if depth[u] >= 0 and depth[v] >= 0:
                cycle_length = abs(depth[u] - depth[v]) + 1
                if cycle_length >= target:
                    # Build the cycle path from u to v via parent pointers
                    path = []
                    if depth[u] > depth[v]:
                        # v is ancestor of u
                        path.append(u)
                        curr = parent[u]
                        while curr != v:
                            path.append(curr)
                            curr = parent[curr]
                        path.append(v)
                    else:
                        # u is ancestor of v
                        path.append(v)
                        curr = parent[v]
                        while curr != u:
                            path.append(curr)
                            curr = parent[curr]
                        path.append(u)

                    return f"2\n{len(path)}\n" + " ".join(map(str, path))

    # Fallback - should never be reached given graph constraints
    return "1\n" + " ".join(map(str, range(1, target + 1)))

import functools

def solution(s):
    """
    Determines if Stepan's dissatisfaction could be exactly equal to k.
    Dissatisfaction is the maximum number of consecutive episodes NOT watched.
    """
    lines = s.split('\n')
    if len(lines) < 2:
        return "NO\n"

    n, k = map(int, lines[0].split())
    t = lines[1]

    # Edge case handling
    if k < 0:
        return "NO\n"
    if k > n:
        return "NO\n"

    # dp(pos, cur_run, max_so_far) returns True if we can achieve max run of exactly k
    # pos: current position in string
    # cur_run: current consecutive run count ending at pos
    # max_so_far: maximum consecutive run encountered so far
    @functools.lru_cache(maxsize=None)
    def dp(pos, cur_run, max_so_far):
        if pos == n:
            return max_so_far == k

        char = t[pos]

        if char == 'N':
            # Definitely not watched - extend current run
            return dp(pos + 1, cur_run + 1, max(max_so_far, cur_run + 1))
        elif char == 'Y':
            # Definitely watched - reset current run
            return dp(pos + 1, 0, max_so_far)
        else:
            # Uncertain - try both 'Y' and 'N'
            # Option 1: Treat as 'N' (not watched)
            res1 = dp(pos + 1, cur_run + 1, max(max_so_far, cur_run + 1))
            # Option 2: Treat as 'Y' (watched)
            res2 = dp(pos + 1, 0, max_so_far)
            return res1 or res2

    result = dp(0, 0, 0)

    return "YES\n" if result else "NO\n"

