def find_digit_at_position(k):
    """Find the digit at position k in the sequence"""
    # Find which block contains position k
    block_length = 0
    block_num = 1

    while True:
        # Calculate length of block_num
        block_len = 0
        for i in range(1, block_num + 1):
            block_len += len(str(i))

        if block_num > 0 and block_len + block_length > k:
            break

        block_length += block_len
        block_num += 1

    # Now we know the digit is in block (block_num - 1)
    num_block = block_num - 1

    # Find which number in the block contains our position
    current_pos = k - block_length

    if current_pos == 0:
        return 1  # First digit of first number in block

    # Find which number in 1, 2, ..., num_block contains the position
    for num in range(1, num_block + 1):
        num_str = str(num)
        if current_pos <= len(num_str):
            return int(num_str[current_pos - 1])
        current_pos -= len(num_str)

    return -1

