    l, r = map(int, input_str.strip().split())

    if l > r:
        return '0\n'

    # Primes p = 2 or p ≡ 1 (mod 4) can be written as sum of two positive squares

    # Sieve small primes up to sqrt(r_max) ≈ 17321
    max_small = 18000
    small_primes = []
    is_prime = bytearray([1]) * max_small
    is_prime[0] = is_prime[1] = 0

    for i in range(2, max_small):
        if is_prime[i]:
            small_primes.append(i)
            for j in range(i*i, max_small, i):
                is_prime[j] = 0

    # Segmented sieve for range [l, r]
    n = r - l + 1
    is_prime_range = bytearray([1]) * n

    for p in small_primes:
        # Find first multiple of p >= l
        start = max(p * p, ((l + p - 1) // p) * p)
        for i in range(start, r + 1, p):
            is_prime_range[i - l] = 0

    # Handle l = 1 (not prime)
    if l == 1:
        is_prime_range[0] = 0

    # Count primes p = 2 or p ≡ 1 (mod 4)
    count = 0
    for i in range(n):
        if is_prime_range[i]:
            p = l + i
            if p == 2 or p % 4 == 1:
                count += 1

    return str(count) + '\n'

