def solution(input_str):
    lines = input_str.strip().split('\n')
    n = int(lines[0])
    x = list(map(int, lines[1].split()))
    a, b = map(int, lines[2].split())

    if a == b:
        return '0\n'

    # BFS to find minimum number of moves from a to b
    dist = {}
    dist[a] = 0
    queue = deque([(a, 0)])

    while queue:
        cur, d = queue.popleft()

        # Option 1: subtract 1
        nxt = cur - 1
        if nxt >= b and nxt not in dist:
            dist[nxt] = d + 1
            queue.append((nxt, d + 1))
            if nxt == b:
                return str(d + 1) + '\n'

        # Option 2: subtract (cur mod xi) for each xi
        for xi in x:
            mod = cur % xi
            if mod > 0:  # Only subtract if mod is positive (otherwise no change)
                nxt = cur - mod
                if nxt >= b and nxt not in dist:
                    dist[nxt] = d + 1
                    queue.append((nxt, d + 1))
                    if nxt == b:
                        return str(d + 1) + '\n'

    return '0\n'

from collections import deque

def solution(input_str):
    lines = input_str.strip().split('\n')

    # Parse input
    n, m = map(int, lines[0].split())
    a = list(map(int, lines[1].split()))
    b = list(map(int, lines[2].split()))

    # Build adjacency list (0-indexed cities)
    adj_list = [[] for _ in range(n)]
    for i in range(m):
        p, q = map(int, lines[3 + i].split())
        adj_list[p - 1].append(q - 1)
        adj_list[q - 1].append(p - 1)

    # Build flow network using adjacency list for efficiency
    # source = 0, city i = i+1, sink = 2*n+1
    source, sink = 0, 2 * n + 1

    # Store original capacities
    source_to_city = list(a)  # capacity from source to city i
    city_to_sink = list(b)    # capacity from city i to sink

    # Adjacency with infinite capacity (bidirectional roads)
    adj_capacity = {}
    for i in range(n):
        for j in adj_list[i]:
            if i <= j:
                adj_capacity[i + 1, j + 1] = float('inf')

    # Edmonds-Karp max flow algorithm
    # flow[u][v] stores flow on edge u->v
    flow = {}
    residual = {}

    # Initialize residual capacities
    for i in range(n):
        residual[(0, i + 1)] = a[i]
        residual[(i + 1, 2 * n + 1)] = b[i]

    # Add road edges (showing min capacity that matters)
    for i in range(n):
        for j in adj_list[i]:
            if i <= j:
                residual[(i + 1, j + 1)] = min(source_to_city[i], city_to_sink[j] if j != i else float('inf'))

    max_flow = 0

    while True:
        # BFS to find shortest augmenting path
        parent = {source: None}
        dist = {source: 0}
        queue = deque([source])

        while queue:
            u = queue.popleft()
            for v in range(1, 2 * n + 2):
                if u in adj_capacity or (u - 1, v - 1) in residual:
                    if residual.get((u, v), 0) > 0 and v not in dist:
                        dist[v] = dist[u] + 1
                        parent[v] = u
                        queue.append(v)
                        if v == sink:
                            break

        if sink not in dist:
            break

        # Find bottleneck capacity along path
        path = []
        v = sink
        while v is not None:
            path.append(v)
            v = parent[v]
        path.reverse()

        bottleneck = float('inf')
        for i in range(len(path) - 1):
            u, v = path[i], path[i + 1]
            bottleneck = min(bottleneck, residual.get((u, v), float('inf')))

        max_flow += bottleneck

        # Update residual capacities
        for i in range(len(path) - 1):
            u, v = path[i], path[i + 1]
            residual[(u, v)] = max(0, residual.get((u, v), float('inf')) - bottleneck)

    if max_flow != sum(b):
        return "NO\n"

    # YES case - extract the movement plan
    # build adjacency for output
    adj_output = [[] for _ in range(n)]
    for i in range(n):
        for j in adj_list[i]:
            adj_output[i].append(j)
        # also include self-stable
        adj_output[i].append(i)

    # Calculate flow on each edge
    flow_matrix = [[0] * n for _ in range(n)]

    for i in range(n):
        for j in range(n):
            if i == j:
                # Soldiers staying in city i = initial - those leaving
                out = sum(flow_matrix[i][k] for k in adj_output[i] if k != i)
                flow_matrix[i][i] = max(0, a[i] - out)
            elif i in adj_output[j] or j in adj_output[i]:
                # Check if connected
                if j in adj_list[i]:
                    u, v = i + 1, j + 1
                    flow_matrix[i][j] = flow.get((u, v), 0)

    # Build result string
    result_lines = []
    for row in flow_matrix:
        result_lines.append(' '.join(map(str, row)))

    return "YES\n" + '\n'.join(result_lines) + '\n'


