def solution(input_str):
    if not input_str.strip():
        return ""

    lines = input_str.strip().split('\n')
    n, m, k = map(int, lines[0].split())

    if n == 1:
        return "0\n\n"

    # Parse all edges with 1-based indices
    edges = []
    for i in range(1, m + 1):
        a, b, w = map(int, lines[i].split())
        edges.append((w, a, b, i))

    # Separate capital edges (incident to city 1) from other edges
    capital_edges = []
    other_edges = []
    for w, a, b, idx in edges:
        if a == 1 or b == 1:
            capital_edges.append((w, a, b, idx))
        else:
            other_edges.append((w, a, b, idx))

    # Check if we have enough capital edges
    if len(capital_edges) < k:
        return "-1\n"

    sort capital_edges by weight to pick the k cheapest
    capital_edges.sort()
    other_edges.sort()  # Sort for Kruskal's

    parent = list(range(n + 1))
    rank = [0] * (n + 1)

    def find(i):
        while parent[i] != i:
            parent[i] = parent[parent[i]]
            i = parent[i]
        return i

    def union(i, j):
        root_i, root_j = find(i), find(j)
        if root_i != root_j:
            if rank[root_i] < rank[root_j]:
                parent[root_i] = root_j
            elif rank[root_i] > rank[root_j]:
                parent[root_j] = root_i
            else:
                parent[root_j] = root_i
                rank[root_i] += 1
            return True
        return False

    # Collect the indices of k cheapest capital edges
    selected_edges = []
    indices_used = set()

    for w, a, b, idx in capital_edges[:k]:
        selected_edges.append(idx)
        if a not in indices_used:
            indices_used.add(a)
            union(a, a)
        if b not in indices_used:
            indices_used.add(b)
            union(b, b)
        union(a, b)

    # Complete the spanning tree using Kruskal's
    final_edges = list(selected_edges)

    for w, a, b, idx in other_edges:
        if find(a) != find(b):
            union(a, b)
            final_edges.append(idx)

    # Verify all cities are connected
    root_between = find(1)
    for city in range(2, n + 1):
        if find(city) != root_between:
            return "-1\n"

    # Verify exactly k capital edges in selection
    capital_count = 0
    for idx in final_edges:
        w, a, b, _ = next(e for e in edges if e[3] == idx)
        if a == 1 or b == 1:
            capital_count += 1

    if capital_count != k:
        return "-1\n"

    return str(len(final_edges)) + "\n" + " ".join(map(str, sorted(final_edges))) + "\n"

