def solution(input_str):
    lines = input_str.strip().split('\n')
    n, m = map(int, lines[0].split())

    # Build adjacency list
    adj = [[] for _ in range(n + 1)]
    for i in range(1, m + 1):
        u, v = map(int, lines[i].split())
        adj[u].append(v)
        adj[v].append(u)

    # Find connected components and their sizes
    visited = [False] * (n + 1)
    components = []

    for i in range(1, n + 1):
        if not visited[i]:
            size = 0
            queue = deque([i])
            visited[i] = True
            while queue:
                node = queue.popleft()
                size += 1
                for neighbor in adj[node]:
                    if not visited[neighbor]:
                        visited[neighbor] = True
                        queue.append(neighbor)
            components.append(size)

    # Sort components by size
    components.sort()

    # Try generating lucky numbers
    # Option 1: Merge existing components using DP
    # Option 2: Use one component + add isolated singletons

    total_comp_size = sum(components)
    isolated_singletons = n - total_comp_size

    min_roads = float('inf')

    if isolated_singletons >= 0:
        # Case 1: Use Lucky numbers that can be formed by components only
        # DP: dp[i] = min components needed to form sum i
        dp = [float('inf')] * (n + 1)
        dp[0] = 0

        for size in components:
            for s in range(n, size - 1, -1):
                if dp[s - size] < float('inf'):
                    dp[s] = min(dp[s], dp[s - size] + 1)

        # Generate lucky numbers lexicographically
        lucky_numbers = []
        for length in range(1, 7):  # up to 10^5
            for mask in range(1 << length):
                num = 0
                for bit in range(length):
                    if mask & (1 << bit):
                        num = num * 10 + 4
                    else:
                        num = num * 10 + 7
                if 0 < num <= n:
                    lucky_numbers.append(num)

        # Check DP for each lucky number
        for l in lucky_numbers:
            if dp[l] < float('inf') and dp[l] >= 1:
                roads_needed = dp[l] - 1
                min_roads = min(min_roads, roads_needed)

        # Case 2: Use single component + add singletons
        for size in components:
            for l in lucky_numbers:
                if l >= size:
                    needed = l - size
                    if needed <= isolated_singletons:
                        min_roads = min(min_roads, needed)
    else:
        # Case 2 only (no singletons)
        for l in lucky_numbers:
            if dp[l] < float('inf') and dp[l] >= 1:
                roads_needed = dp[l] - 1
                min_roads = min(min_roads, roads_needed)

    if min_roads == float('inf'):
        return "-1\n"
    else:
        return f"{min_roads}\n"


