            if i == 0 and j == 0:
                continue

            val = cnt5[i][j]
            if i == 0:
                dp5[i][j] = dp5[i][j-1] + val
                path5[i][j] = path5[i][j-1] + 'R'
            elif j == 0:
                dp5[i][j] = dp5[i-1][j] + val
                path5[i][j] = path5[i-1][j] + 'D'
            else:
                from_top = dp5[i-1][j] + val
                from_left = dp5[i][j-1] + val
                if from_top <= from_left:
                    dp5[i][j] = from_top
                    path5[i][j] = path5[i-1][j] + 'D'
                else:
                    dp5[i][j] = from_left
                    path5[i][j] = path5[i][j-1] + 'R'

    # Evaluate paths
    final2 = dp2[n-1][n-1]
    final5 = dp5[n-1][n-1]

    zeros2 = min(final2, final5)
    zeros5 = min(final2, final5)

    # Use the better one
    if zeros2 <= zeros5:
        zeros = zeros2
        path = path2[n-1][n-1][1:]
    else:
        zeros = zeros5
        path = path5[n-1][n-1][1:]

    return f"{zeros}\n{path}"

